/**
 * SimpleUploadModal - Simple file upload modal
 *
 * Pick file → Validate → Upload → Done.
 * Uses async_store=true for deferred ingestion.
 */

import { useState, useCallback } from 'react';
import { Modal, Upload, Button, Alert, Progress, Typography, Tag } from 'antd';
import type { UploadFile, UploadProps } from 'antd';
import { InboxOutlined, FileTextOutlined, CheckCircleOutlined, CloseCircleOutlined } from '@ant-design/icons';
import { tokens } from '@lumina/design-system';
import { useUploadDataset } from '../hooks';

const { Dragger } = Upload;
const { Text } = Typography;

interface SimpleUploadModalProps {
    open: boolean;
    onClose: () => void;
    projectId: string;
    onSuccess?: () => void;
}

const MAX_FILE_SIZE_MB = 100;
const SUPPORTED_FORMATS = ['csv', 'xes'];

// Format file size for display
function formatFileSize(bytes: number): string {
    if (bytes < 1024) return `${bytes} B`;
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
    return `${(bytes / 1024 / 1024).toFixed(2)} MB`;
}

export function SimpleUploadModal({
    open,
    onClose,
    projectId,
    onSuccess,
}: SimpleUploadModalProps) {
    // Store the actual File object separately for reliable access to name/size
    const [selectedFile, setSelectedFile] = useState<File | null>(null);
    const [fileList, setFileList] = useState<UploadFile[]>([]);
    const [error, setError] = useState<string | null>(null);
    const uploadMutation = useUploadDataset();

    const validateFile = useCallback((file: File): string | null => {
        // Check file size
        if (file.size > MAX_FILE_SIZE_MB * 1024 * 1024) {
            return `File size exceeds ${MAX_FILE_SIZE_MB}MB limit`;
        }

        // Check file extension - support CSV and XES
        const ext = file.name.split('.').pop()?.toLowerCase();
        if (!ext || !SUPPORTED_FORMATS.includes(ext)) {
            return `Unsupported format. Accepted: ${SUPPORTED_FORMATS.join(', ').toUpperCase()}`;
        }

        return null;
    }, []);

    const handleUpload = useCallback(async () => {
        if (!selectedFile) return;

        setError(null);
        console.log('[Upload] Starting upload:', selectedFile.name, selectedFile.size);

        try {
            await uploadMutation.mutateAsync({
                projectId,
                file: selectedFile,
                name: selectedFile.name,
            });
            setFileList([]);
            setSelectedFile(null);
            onSuccess?.();
            onClose();
        } catch (err) {
            // Error is already handled by the mutation
            console.error('[Upload] Failed:', err);
        }
    }, [selectedFile, projectId, uploadMutation, onSuccess, onClose]);

    const uploadProps: UploadProps = {
        accept: SUPPORTED_FORMATS.map(f => `.${f}`).join(','),
        maxCount: 1,
        fileList,
        showUploadList: false, // We'll show our own file display
        beforeUpload: (file) => {
            console.log('[Upload] File selected:', file.name, file.size, file.type);

            const validationError = validateFile(file);
            if (validationError) {
                setError(validationError);
                setSelectedFile(null);
                setFileList([]);
                return Upload.LIST_IGNORE;
            }

            setError(null);
            setSelectedFile(file);
            setFileList([{
                uid: file.name,
                name: file.name,
                size: file.size,
                type: file.type,
                status: 'done',
                originFileObj: file,
            } as UploadFile]);

            return false; // Prevent auto upload
        },
        onRemove: () => {
            setFileList([]);
            setSelectedFile(null);
            setError(null);
        },
    };

    const handleClose = () => {
        setFileList([]);
        setSelectedFile(null);
        setError(null);
        onClose();
    };

    const handleRemoveFile = () => {
        setFileList([]);
        setSelectedFile(null);
        setError(null);
    };

    const fileExtension = selectedFile?.name.split('.').pop()?.toUpperCase();

    return (
        <Modal
            title="Add Dataset"
            open={open}
            onCancel={handleClose}
            footer={[
                <Button key="cancel" onClick={handleClose}>
                    Cancel
                </Button>,
                <Button
                    key="upload"
                    type="primary"
                    onClick={handleUpload}
                    loading={uploadMutation.isPending}
                    disabled={!selectedFile || !!error}
                >

/**
 * useUploadDataset - Hook for uploading files with deferred ingestion
 *
 * Uses async_store=true to create UNSTRUCTURED dataset without parsing.
 * 
 * BUG-043 FIX: Added auth header injection
 * BUG-045 FIX: Added AbortController support
 */

import { useMutation, useQueryClient } from '@tanstack/react-query';
import { message } from 'antd';
import { queryKeys, instrumentedFetch } from '@lumina/design-system';
import { env } from '../../../../config/env';

interface UploadDatasetParams {
    projectId: string;
    file: File;
    name?: string;
    signal?: AbortSignal;
}

interface UploadDatasetResponse {
    id: string;
    name: string;
    status: string;
    sourceFormat: string;
    createdAt: string;
}

const MAX_FILE_SIZE_MB = 100;

// BUG-043 FIX: Get auth token for uploads
function getAuthToken(): string | null {
    return localStorage.getItem('auth_token');
}

async function uploadDataset({
    projectId,
    file,
    name,
    signal,
}: UploadDatasetParams): Promise<UploadDatasetResponse> {
    // Validate file size
    if (file.size > MAX_FILE_SIZE_MB * 1024 * 1024) {
        throw new Error(`File size exceeds ${MAX_FILE_SIZE_MB}MB limit`);
    }

    // Validate file extension - support CSV and XES formats
    const ext = file.name.split('.').pop()?.toLowerCase();
    if (ext !== 'csv' && ext !== 'xes') {
        throw new Error('Supported formats: CSV, XES');
    }

    const formData = new FormData();
    formData.append('file', file);
    formData.append('async_store', 'true');
    console.log('[Upload] Setting async_store=true for deferred ingestion');
    formData.append('project_id', projectId);
    if (name) {
        formData.append('name', name);
    }

    // Use API base URL from environment config
    const apiUrl = `${env.API_BASE_URL}/api/v1/datasets/`;
    console.log('[Upload] Uploading to:', apiUrl, 'projectId:', projectId);

    // BUG-043 FIX: Add auth headers (no Content-Type for FormData)
    const headers: Record<string, string> = {};
    const token = getAuthToken();
    if (token) {
        headers['Authorization'] = `Bearer ${token}`;
    }

    // BUG-045 FIX: Add abort signal
    // Note: Using instrumentedFetch for DevConsole visibility
    const response = await instrumentedFetch(apiUrl, {
        method: 'POST',
        headers,
        body: formData,
        signal,
    });

    if (!response.ok) {
        const error = await response.json().catch(() => ({ detail: 'Upload failed' }));
        console.error('[Upload] Error:', error);
        throw new Error(error.detail || 'Failed to upload file');
    }

    const result = await response.json();
    console.log('[Upload] Success:', result);
    return result;
}

export function useUploadDataset() {
    const queryClient = useQueryClient();

    return useMutation({
        mutationFn: uploadDataset,
        onSuccess: (data) => {
            message.success(`Dataset "${data.name}" uploaded successfully`);
            // Invalidate project queries to refresh the dataset list
            queryClient.invalidateQueries({ queryKey: queryKeys.projects.all() });
        },
        onError: (error: Error) => {
            // BUG-045 FIX: Don't show error for aborted requests
            if (error.name === 'AbortError') {
                console.log('[Upload] Request was cancelled');
                return;
            }
            message.error(error.message || 'Failed to upload dataset');
        },
    });
}

